"""Minimum Insertions and Deletions — derived from the LCS length.

Time: O(n*m)   Space: O(m)
"""


class Solution:
    def minOperations(self, str1: str, str2: str) -> int:
        previous = [0] * (len(str2) + 1)
        for a in str1:
            current = [0]
            for j, b in enumerate(str2):
                if a == b:
                    current.append(previous[j] + 1)
                else:
                    current.append(max(previous[j + 1], current[j]))
            previous = current
        lcs = previous[-1]
        return (len(str1) - lcs) + (len(str2) - lcs)
